import assert from 'node:assert/strict';import path from'node:path';import{readFile,writeFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{applyComponents}from'../../scripts/component-export.mjs';
const artifact=path.resolve('artifacts/platform/events-heldout'),generated=process.argv.includes('--generated');let server,browser;const cases=[];
try{server=await serveStatic(path.join(artifact,'project/output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390])for(const [view,route]of [['day','/events/2028-03-11/'],['month','/events/month/2028-03/']]){const pair=[];for(const [kind,origin]of [['source','http://127.0.0.1:9440'],['export',server.url]]){const page=await browser.newPage({viewport:{width,height:900}});if(kind==='export'&&!generated)await page.route(server.url+route,async r=>{const $=load(await readFile(path.join(artifact,'project/output',route,'index.html'),'utf8'));applyComponents($);await r.fulfill({contentType:'text/html',body:$.html()});});await page.goto(origin+route,{waitUntil:'networkidle'});const button=page.locator('.tribe-events-c-top-bar__datepicker-button');await button.click();const picker=page.locator('.datepicker:visible');await picker.waitFor();const bounds=await picker.boundingBox();await picker.screenshot({path:path.join(artifact,`picker-${kind}-${view}-${width}.png`)});pair.push({kind,bounds,text:(await picker.innerText()).replace(/\s+/g,' ').trim()});if(kind==='export'){if(view==='day'){await picker.locator('.day').filter({hasText:/^12$/}).click();await page.waitForURL('**calendar-date=2028-03-12');}else{await picker.locator('.month').filter({hasText:/^Apr$/}).click();await page.waitForURL('**calendar-date=2028-04-01');}await button.click();await page.locator('.datepicker:visible').waitFor();await page.keyboard.press('Escape');assert.equal(await page.locator('.datepicker').count(),0);assert.equal(await button.evaluate(e=>e===document.activeElement),true);}await page.close();}
  console.log(JSON.stringify({width,view,pair}));for(const dimension of ['width','height'])assert.ok(Math.abs(pair[0].bounds[dimension]-pair[1].bounds[dimension])<2,`${width} ${view} ${dimension} differs`);cases.push({width,view,pair,localSelection:true,escapeFocus:true});}
 await writeFile(path.join(artifact,generated?'picker-generated-check.json':'picker-candidate-check.json'),JSON.stringify({scope:'Initial picker geometry, local day/month selection and Escape at two widths; further configurations pending',cases},null,2));
}finally{await browser?.close();await server?.close();}
